pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // 1️⃣ Base waste after placing the item
    let mut score = post_residual as f64;

    // 2️⃣ Early‑stream urgency: penalize bins that cannot accommodate the next item
    if next_item_size > 0 && post_residual < next_item_size {
        let stream_progress = step_index as f64 / total_items as f64;
        let early_factor = 1.0 + stream_progress.sqrt();
        score += (next_item_size - post_residual) as f64 * 4.0 * early_factor;
    } else if post_residual < 5 {
        // Tiny gaps are always bad
        score += 12.0;
    }

    // 3️⃣ Reward the unique fit
    if fitting_bins_count == 1 {
        score -= 28.0;
    }

    // 4️⃣ Penalize too many open bins (marginally)
    score += (open_bins_count as f64).sqrt() * 1.8;

    // 5️⃣ New‑bin logic: weigh mean residual and future demand
    if bin_residual == bin_capacity {
        // When overall waste is low and many bins fit, prefer a new bin
        if mean_residual < 28.0 && fitting_bins_count > 3 {
            score -= 18.0;
        } else {
            // Otherwise, open a new bin only if the next item is large
            if next_item_size > (bin_capacity / 2) {
                score -= 5.0;
            } else {
                score += 22.0;
            }
        }
    }

    // 6️⃣ Slight penalty if the overall packing is poor
    if mean_residual > 38.0 {
        score += (mean_residual - 38.0) * 0.04;
    }

    // 7️⃣ Favor tight residual relative to capacity
    let capacity_ratio = bin_residual as f64 / bin_capacity as f64;
    if capacity_ratio > 0.85 {
        score -= 4.5;
    } else if capacity_ratio < 0.2 {
        // Very low fill: heavy penalty
        score += 10.0;
    }

    // 8️⃣ End‑of‑stream tightening: prefer tighter packing later
    if step_index > total_items / 2 {
        score += 4.0;
    }

    // 9️⃣ Add curvature: diminishing returns on waste
    score += (post_residual as f64).sqrt() * 0.45;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Reject bins that cannot hold the item
    if bin_residual < item_size {
        return f64::INFINITY;
    }

    // Basic ratios
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    let cap_ratio = bin_residual as f64 / bin_capacity as f64;
    let remaining_ratio = (total_items - step_index) as f64 / total_items as f64;

    // Base score: lower is better
    let mut score = 1.0 + waste_ratio * 8.0; // prioritize minimal waste

    // Next‑item fit heuristic
    if next_item_size > 0 {
        if next_item_size <= bin_residual {
            // Good fit for next item
            score -= 4.0 + cap_ratio * 2.5;
        } else {
            // Next item will not fit, penalize if fragment is tiny
            if bin_residual - item_size < 4 {
                score += 4.0;
            }
        }
    }

    // Residual balance: avoid bins that are almost empty or almost full
    if cap_ratio < 0.35 {
        score += 1.5;
    }
    if cap_ratio > 0.92 {
        score -= 3.0;
    }

    // Remaining items influence
    if remaining_ratio > 0.7 {
        score -= cap_ratio * 1.8;
    } else {
        score += (1.0 - cap_ratio) * 1.2;
    }

    // Penalize opening many bins
    score += (open_bins_count as f64).ln() * 0.4;

    // New‑bin candidate logic
    if bin_residual == bin_capacity {
        // Empty bin: decide whether to open a new one
        if mean_residual > 68.0 || fitting_bins_count < 3 {
            score += 9.0; // discourage opening
        } else {
            score -= 12.0; // encourage opening
        }
        if open_bins_count > 4 {
            score += 2.5;
        }
    }

    // Mean residual penalty
    if mean_residual > 58.0 {
        score += (mean_residual - 58.0) * 0.015;
    }

    // Single‑fit bin penalty
    if fitting_bins_count == 1 {
        score += 14.0;
    }

    // Mid‑stream bonus
    if step_index > total_items / 3 {
        score -= 1.2;
    }

    // Non‑linear waste adjustment
    score += waste_ratio.powf(1.4) * 4.5;

    // Final scaling
    score * 0.92 + waste_ratio * 0.08
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    _step_index: usize,
    _total_items: usize,
