    fitting_bins_count: usize,
) -> f64 {
    // Base score is the remaining space after placement
    let mut score = post_residual as f64;

    // Reward bins that are the last possible fit before opening a new bin
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Penalize dead space that cannot accommodate the next item
    if next_item_size > 0 && post_residual < next_item_size {
        // Larger gap relative to next item size → larger penalty
        score += (next_item_size - post_residual) as f64 * 2.0;
    } else if post_residual < 5 {
        // Very small gaps are always bad
        score += 20.0;
    }

    // Pressure to reduce the number of open bins
    score += open_bins_count as f64 * 1.5;

    // New‑bin candidate penalty (unless a better fit exists)
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Slightly penalize high average residuals to encourage tighter packing
    if mean_residual > 50.0 {
        score += (mean_residual - 50.0) * 0.1;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Baseline waste after placing the item
    let mut score = post_residual as f64;

    // Waste ratio (0..1)
    let waste_ratio = post_residual as f64 / bin_capacity as f64;

    // Fraction of items still to be processed
    let remaining_frac = (total_items - step_index) as f64 / total_items as f64;

    // Tight gaps early in the stream are especially costly
    if waste_ratio < 0.08 && remaining_frac > 0.6 {
        score += 18.0 * (0.08 - waste_ratio);
    }

    // Very small gaps are bad whenever we still have many items
    if waste_ratio < 0.02 && remaining_frac > 0.5 {
        score += 12.0;
    }

    // Look‑ahead penalty – penalise when the next item won’t fit
    if next_item_size > 0 && next_item_size > post_residual {
        let diff = (next_item_size - post_residual) as f64;
        let amp = 1.0 + (next_item_size as f64 / bin_capacity as f64).sqrt();
        score += diff * 2.2 * amp;
        // Extra penalty if the next item is huge relative to the bin
        if next_item_size as f64 > 0.7 * bin_capacity as f64 {
            score += diff * 1.5;
        }
    } else if waste_ratio < 0.04 {
        // Tiny gaps after a good fit are still undesirable
        score += 9.0;
    }

    // Reward a unique perfect fit
    if fitting_bins_count == 1 {
        score -= 28.0;
    }

    // Penalise having too many open bins – diminishing returns
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // New‑bin candidate logic
    if bin_residual == bin_capacity {
        // Opening a fresh bin is attractive only if the overall waste is low
        if mean_residual < 20.0 && fitting_bins_count > 4 {
            score -= 20.0;
        } else {
            score += 26.0;
        }
    }

    // Mild penalty for high average residuals
    if mean_residual > 40.0 {
        score += (mean_residual - 40.0) * 0.05;
    }

    // Prefer bins that leave a very small residual relative to capacity
    let cap_ratio = bin_residual as f64 / bin_capacity as f64;
    if cap_ratio > 0.9 {
        score -= 3.0;
    }

    // End‑of‑stream urgency – tighter packing is more valuable
    if step_index > total_items * 3 / 4 {
        score += 6.0;
    }

    // Curvature to waste influence
    score += waste_ratio.sqrt() * 0.7 * bin_capacity as f64;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    let cap_ratio = bin_residual as f64 / bin_capacity as f64;
    let remaining_ratio = (total_items - step_index) as f64 / total_items as f64;

    // Base score: prefer less waste
    let mut score = (1.0 - waste_ratio) * 5.0;

    // Favor bins that can also accommodate the next item
    if next_item_size > 0 && next_item_size <= bin_residual {
        score += 3.0 + cap_ratio * 2.0;
    } else if next_item_size > 0 && next_item_size > bin_residual {
        // Penalise bins that would leave the next item unplaced
        score -= (next_item_size as f64 - bin_residual as f64) * 0.02;
    }

    // Penalise high residual when many items remain
    if waste_ratio > 0.15 && remaining_ratio > 0.3 {
        score -= (waste_ratio - 0.15) * 20.0;
    }

    // Slightly penalise many open bins to encourage reuse
    score -= (open_bins_count as f64).ln() * 0.5;

    // New‑bin candidate handling
    if bin_residual == bin_capacity {
        if mean_residual < 20.0 && fitting_bins_count > 2 {
            score += 12.0;
        } else {
            score -= 8.0;
        }
        // Extra penalty if too many bins are already open
        if open_bins_count > 5 {
            score -= 4.0;
        }
    }

    // High overall residual pushes towards tighter packing
    if mean_residual > 55.0 {
        score -= (mean_residual - 55.0) * 0.03;
    }

    // Very full bins are discouraged
    if cap_ratio > 0.9 {
        score -= 5.0;
    }

    // If only one fitting bin, heavily discourage it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // When the stream is halfway through, favour better fits
    if step_index > total_items / 2 {
        score += 1.5;
    }

    // Non‑linear smoothing of waste
    score += waste_ratio.sqrt() * 0.4 * bin_capacity as f64;

    // Final weighted combination
    score * 0.65 + waste_ratio * 0.35
}
